// The OTHER billing option of the host seam: Cyrus with its own Stripe account (no platform wallet). Not used anywhere
// today; the default stays "the host is the payment provider" (host/nxeon.ts inside Nxeon, the wallet over the HTTP
// adapter outside). This is a ready adapter, not an owner decision. SERVER ONLY. HOST SEAM: no platform imports.
import Stripe from "stripe";
import type { HostBilling } from "./types";

export type OwnStripeOptions = {
  secretKey: string;
  publishableKey: string;
  /** Cyrus' own store for the customer id it creates (its accounts table). */
  saveCustomerId(userId: string, customerId: string): Promise<void>;
  /** Same values Nxeon uses today, so the checkout UI is unchanged. */
  apiVersion?: string;
  client?: Stripe;
};

export function ownStripeBilling(o: OwnStripeOptions): HostBilling {
  let client: Stripe | null = o.client ?? null;
  const get = () => {
    if (!o.secretKey && !o.client) throw new Error("Stripe is not configured");
    return (client ??= new Stripe(o.secretKey));
  };
  return {
    provider: "own-stripe",
    wallet: null,
    stripe: {
      configured: () => !!o.secretKey || !!o.client,
      client: get,
      publishableKey: () => o.publishableKey,
      createCheckoutSession: (params, options) => get().checkout.sessions.create(params, options),
      uiMode: "elements",
      requestOptions: { apiVersion: o.apiVersion ?? "2026-03-25.dahlia" } as unknown as Stripe.RequestOptions,
      async ensureCustomer(user) {
        if (user.stripeCustomerId) return user.stripeCustomerId;
        // keyed on the stable account id: a retried call replays the first customer instead of creating a second
        const c = await get().customers.create({ email: user.email, name: user.name ?? undefined, metadata: { cyrusUserId: user.id } }, { idempotencyKey: `cyrus-customer-${user.id}` });
        await o.saveCustomerId(user.id, c.id);
        return c.id;
      },
    },
  };
}
