function fakePlatform() {
  const state = {
    users: new Map([["u1", { id: "u1", email: "Owner@Example.com" }], ["u2", { id: "u2", email: "two@preview.test" }]]),
    billing: new Map<string, string>(),
    settings: new Map<string, string>([["cyrus_x", "1"], ["cyrus_n", "7"], ["other", "o"]]),
    audit: [] as unknown[],
    sweeps: 0,
    fs: new MemFs(),
    signedIn: "u1" as string | null,
  };
  const S1: HostServerRow = { id: "s1", status: "ACTIVE", label: "My server", hostname: "mc-1", gameVariant: "paper", gameConfig: { VERSION: "1.21.11" }, osTemplate: { family: "minecraft" } };
  const T = new Date("2026-10-09T10:00:00Z");
  const install: HostInstallRow = { serverId: "s1", modId: "gm1", versionId: "v1", status: "INSTALLED", error: null, updatedAt: T, autoUpdate: null, mod: { source: "cyrus", sourceId: "b1", name: "CoinShop" } };
  const host: CyrusHost = {
    db: {} as CyrusDb,
    auth: {
      currentUser: async () => (state.signedIn ? { ...state.users.get(state.signedIn)!, role: "USER" } : null),
      realUser: async () => (state.signedIn ? { ...state.users.get(state.signedIn)!, role: "USER" } : null),
      requireArea: async () => { throw new Error("redirect"); },
    },
    access: {
      canAccess: (role, area) => ({ ADMIN: ["billing", "support"] } as Record<string, string[]>)[role]?.includes(area) ?? false,
      isPreviewUser: async (u) => !!u?.email?.endsWith("@preview.test"),
    },
    settings: {
      get: async (k, f) => state.settings.get(k) ?? f ?? "",
      getBool: async (k, f) => (state.settings.has(k) ? state.settings.get(k) === "1" : f ?? false),
      getInt: async (k, f) => (state.settings.has(k) ? Number(state.settings.get(k)) : f ?? 0),
      getAll: async () => Object.fromEntries(state.settings),
      set: async (k, v) => { state.settings.set(k, v); },
      readStored: async (keys) => Object.fromEntries(keys.filter((k) => state.settings.has(k)).map((k) => [k, state.settings.get(k)!])),
      readStoredPrefix: async (p) => Object.fromEntries([...state.settings].filter(([k]) => k.startsWith(p))),
      writeStored: async (k, v) => { state.settings.set(k, v); },
      clearStored: async (k) => { state.settings.delete(k); },
    },
    rateLimit: (() => { const w = new Map<string, { start: number; n: number }>(); return { check(key: string, { max, windowMs }: { max: number; windowMs: number }) { const t = Date.now(); let x = w.get(key); if (!x || t - x.start >= windowMs) { x = { start: t, n: 0 }; w.set(key, x); } x.n++; return { ok: x.n <= max, remaining: Math.max(0, max - x.n), retryAfterSec: x.n <= max ? 0 : 1 }; } }; })(),
    worker: {
      modLifecycleSweep: async () => ({ swept: ++state.sweeps }),
      modCompatWatchSweep: async () => ({ swept: ++state.sweeps }),
      syncModBuilds: async () => ({ swept: ++state.sweeps }),
    },
    users: {
      get: async (id) => state.users.get(id) ?? null,
      emails: async (ids) => ids.map((i) => state.users.get(i)).filter((u): u is { id: string; email: string } => !!u),
      find: async (q) => (q.includes("@") ? [...state.users.values()].find((u) => u.email.toLowerCase() === q.toLowerCase()) : state.users.get(q)) ?? null,
      setBillingCustomerId: async (u, c) => { state.billing.set(u, c); },
    },
    jobs: { lastDone: async (sid) => (sid === "s1" ? { updatedAt: T, payload: { ok: true } } : null) },
    servers: {
      get: async (id) => (id === "s1" ? S1 : null),
      listForUser: async (u) => (u === "u1" ? [S1] : []),
      familyOf: (s) => s.osTemplate?.family ?? null,
      planFamily: async (id) => (id === "s1" ? "minecraft" : null),
      paidCount: async (u) => (u === "u1" ? 1 : 0),
      lastHealthRun: async (id) => (id === "s1" ? { startedAt: T, plan: { verdict: "ok" } } : null),
      openFiles: async (u, sid) => (u === "u1" && sid === "s1" ? { fs: state.fs, base: "/opt/mc" } : null),
      pinnedVersion: (c) => platformPinnedVersion(c),
    },
    records: {
      onServer: async (sid, src) => (sid === "s1" && src === "cyrus" ? [install] : []),
      serversWithSource: async (ids, src) => (src === "cyrus" ? ids.filter((i) => i === "s1") : []),
      catalogId: async (src, sid) => (src === "cyrus" && sid === "b1" ? "gm1" : null),
      ofMod: async (m, ids) => (m === "gm1" && ids.includes("s1") ? [{ serverId: "s1", modId: "gm1", versionId: "v1", status: "INSTALLED", error: null, updatedAt: T, autoUpdate: null }] : []),
    },
    installs: {
      statePath: "/opt/mc/.nxeon-mods/state.json",
      async install({ fs, mod, resolution }) {
        const pkg = resolution.packages[0];
        if (!pkg?.prefetched) return { ok: false, error: "no bytes" };
        await fs.writeFile(`/opt/mc/plugins/${pkg.file.filename}`, pkg.prefetched);
        return { ok: true, version: pkg.version, fileName: pkg.file.filename, restartRequired: true, changed: [`plugins/${pkg.file.filename}`], notes: [mod.name] };
      },
      async uninstall({ fs }) { await fs.remove("/opt/mc/plugins/CoinShop.jar"); return { ok: true, restartRequired: true, changed: ["plugins/CoinShop.jar"], notes: [] }; },
    },
    audit: {
      record: async (userId, action, detail) => { state.audit.push({ userId, action, detail }); },
      append: async (row) => { state.audit.push(row); },
    },
  };
  return { host, state };
}

// ------------------------------------------------------------------------------------------------ conformance
const BYTES = Buffer.from(Array.from({ length: 256 }, (_, i) => i));

async function conformance(host: CyrusHost, state: ReturnType<typeof fakePlatform>["state"]) {
  // users
  assert.deepEqual(await host.users.get("u1"), { id: "u1", email: "Owner@Example.com" });
  assert.equal(await host.users.get("nobody"), null);
  assert.deepEqual((await host.users.emails(["u2", "u1", "x"])).map((u) => u.id), ["u2", "u1"]);
  assert.equal((await host.users.find("owner@example.com"))?.id, "u1");
  await host.users.setBillingCustomerId("u1", "cus_123");
  assert.equal(state.billing.get("u1"), "cus_123");
  // auth + access
  assert.equal((await host.auth.currentUser())?.id, "u1");
  assert.equal((await host.auth.realUser())?.role, "USER");
  assert.equal(host.access.canAccess("ADMIN", "billing"), true);
  assert.equal(host.access.canAccess("USER", "billing"), false);
  assert.equal(host.access.canAccess("GHOST", "nothing"), false);
  assert.equal(await host.access.isPreviewUser({ email: "two@preview.test" }, "modbuilder"), true);
  assert.equal(await host.access.isPreviewUser(null, "modbuilder"), false);
  // settings
  assert.equal(await host.settings.get("missing", "fb"), "fb");
  await host.settings.set("cyrus_flag", "1");
  assert.equal(await host.settings.get("cyrus_flag"), "1");
  assert.equal(await host.settings.getBool("cyrus_flag"), true);
  assert.equal(await host.settings.getInt("cyrus_n"), 7);
  assert.deepEqual(await host.settings.readStored(["cyrus_x", "nope"]), { cyrus_x: "1" });
  assert.deepEqual(Object.keys(await host.settings.readStoredPrefix("cyrus_")).sort(), ["cyrus_flag", "cyrus_n", "cyrus_x"]);
  await host.settings.writeStored("cyrus_w", "w");
  await host.settings.clearStored("cyrus_w");
  assert.deepEqual(await host.settings.readStored(["cyrus_w"]), {});
  assert.equal((await host.settings.getAll()).other, "o");
  // rate limit (local on both)
  const k = `rl-${Math.random()}`;
  assert.deepEqual([1, 2, 3].map(() => host.rateLimit.check(k, { max: 2, windowMs: 60_000 }).ok), [true, true, false]);
  // servers, jobs, records (Dates survive)
  const s1 = await host.servers.get("s1");
  assert.equal(s1?.hostname, "mc-1");
  assert.equal(host.servers.familyOf(s1!), "minecraft");
  assert.equal(await host.servers.get("s9"), null);
  assert.deepEqual((await host.servers.listForUser("u1")).map((s) => s.id), ["s1"]);
  assert.equal(await host.servers.planFamily("s1"), "minecraft");
  assert.equal(await host.servers.paidCount("u1"), 1);
  const hr = await host.servers.lastHealthRun("s1");
  assert.ok(hr?.startedAt instanceof Date); assert.deepEqual(hr?.plan, { verdict: "ok" });
  const job = await host.jobs.lastDone("s1", ["MOD_INSTALL"]);
  assert.ok(job?.updatedAt instanceof Date);
  const recs = await host.records.onServer("s1", "cyrus");
  assert.equal(recs[0].mod.name, "CoinShop"); assert.ok(recs[0].updatedAt instanceof Date);
  assert.deepEqual(await host.records.serversWithSource(["s1", "s2"], "cyrus"), ["s1"]);
  assert.equal(await host.records.catalogId("cyrus", "b1"), "gm1");
  assert.equal((await host.records.ofMod("gm1", ["s1"])).length, 1);
  assert.equal(host.servers.pinnedVersion({ VERSION: "1.21.11" }), "1.21.11");
  assert.equal(host.servers.pinnedVersion({ VERSION: "latest" }), null);
  // files (binary-safe) + installs through the same session
  assert.equal(await host.servers.openFiles("u2", "s1"), null, "not the user's server");
  const f = await host.servers.openFiles("u1", "s1");
  assert.ok(f); assert.equal(f.base, "/opt/mc");
  await f.fs.writeFile("/opt/mc/config/a.bin", BYTES);
  assert.deepEqual(await f.fs.readFile("/opt/mc/config/a.bin"), BYTES);
  assert.equal((await f.fs.readFile("/opt/mc/config/a.bin", 4))?.length, 4);
  assert.deepEqual(await f.fs.stat("/opt/mc/config/a.bin"), { type: "file", size: 256 });
  await f.fs.copy("/opt/mc/config/a.bin", "/opt/mc/config/b.bin");
  await f.fs.rename("/opt/mc/config/b.bin", "/opt/mc/config/c.bin");
  await f.fs.mkdirp("/opt/mc/world/data");
  await f.fs.chownLike("/opt/mc", ["/opt/mc/config/c.bin"]);
  assert.deepEqual(await f.fs.list("/opt/mc/config"), ["a.bin", "c.bin"]);
  await f.fs.remove("/opt/mc/config/c.bin");
  assert.equal(await f.fs.stat("/opt/mc/config/c.bin"), null);
  assert.equal(host.installs.statePath, "/opt/mc/.nxeon-mods/state.json");
  const jar = Buffer.concat([Buffer.from("PK\u0003\u0004"), BYTES]);
  const server = { id: "s1", family: "minecraft", variant: "paper", pinnedVersion: "1.21.11", config: null };
  const mod = { id: "gm1", gameFamily: "minecraft", slug: "coinshop", name: "CoinShop", source: "cyrus", sourceId: "b1", url: null, category: "plugin", appliesToVariant: null, loaders: ["paper"], gameVersions: ["1.21.11"], serverSide: "required" };
  const r = await host.installs.install({
    fs: f.fs, server, mod, mode: "install", noDownloadMessage: "no downloads",
    resolution: { notes: [], packages: [{ key: "coinshop", name: "CoinShop", version: "1.0.0", file: { url: "cyrus://b1", filename: "CoinShop.jar", size: jar.length, hashes: {} }, placement: "plugin-jar", requires: [], incompatible: [], prefetched: jar, root: true }] },
  });
  assert.deepEqual(r, { ok: true, version: "1.0.0", fileName: "CoinShop.jar", restartRequired: true, changed: ["plugins/CoinShop.jar"], notes: ["CoinShop"] });
  assert.deepEqual(state.fs.files.get("/opt/mc/plugins/CoinShop.jar"), jar, "the exact bytes landed on the server");
  assert.equal((await host.installs.uninstall({ fs: f.fs, server, mod, noDownloadMessage: "x" })).ok, true);
  assert.equal(state.fs.files.has("/opt/mc/plugins/CoinShop.jar"), false);
  f.close?.();
  // audit + worker
  const before = state.audit.length;
  await host.audit.record("u1", "cyrus.test", "detail");
  await host.audit.append({ userId: null, action: "cyrus.admin", category: "cyrus", target: "b1" });
  assert.equal(state.audit.length, before + 2);
  assert.ok(((await host.worker.syncModBuilds()) as { swept: number }).swept > 0);
}

