// Cyrus API v1 idempotency for writes. A write carries `Idempotency-Key`; the first request with a key runs, every
// later one with the SAME key and the SAME request gets the first response back (header idempotent-replay: true), the
// same key with a DIFFERENT request is refused (422 idempotency_mismatch), and a key whose first request is still
// running answers 409 idempotency_in_flight. Scope = token key + subject + operation + key, so two clients never collide.
// 5xx answers are not stored (the caller may retry). Pure; the memory store is one process only. The table for a
// multi-instance store is proposed in prisma/manual-migration-cyrus-api-v1.sql (NOT run).
import { createHash } from "node:crypto";

export const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_.:-]{8,128}$/;
/** OWNER: retention (proposed 24 h, same as the webhook replay window). */
export const IDEMPOTENCY_TTL_MS = 24 * 3600_000;

export type StoredReply = { status: number; body: unknown };
export type IdempotencyBegin = { state: "new" } | { state: "replay"; reply: StoredReply } | { state: "mismatch" } | { state: "in_flight" };
export interface IdempotencyStore {
  begin(scope: string, requestHash: string, nowMs: number): Promise<IdempotencyBegin>;
  finish(scope: string, reply: StoredReply, nowMs: number): Promise<void>;
  /** the first request failed (5xx/throw): forget the key so a retry runs again */
  abort(scope: string): Promise<void>;
}

export const requestHash = (method: string, path: string, body: string) => createHash("sha256").update(`${method.toUpperCase()}\n${path}\n${body}`).digest("hex");

export function createMemoryIdempotencyStore(max = 20_000): IdempotencyStore & { size(): number } {
  const m = new Map<string, { hash: string; at: number; reply: StoredReply | null }>();
  const sweep = (now: number) => {
    for (const [k, v] of m) { if (v.at + IDEMPOTENCY_TTL_MS < now || m.size > max) m.delete(k); else break; }
  };
  return {
    async begin(scope, hash, now) {
      sweep(now);
      const hit = m.get(scope);
      if (!hit) { m.set(scope, { hash, at: now, reply: null }); return { state: "new" }; }
      if (hit.hash !== hash) return { state: "mismatch" };
      return hit.reply ? { state: "replay", reply: hit.reply } : { state: "in_flight" };
    },
    async finish(scope, reply, now) {
      const hit = m.get(scope);
      if (hit) { hit.reply = reply; hit.at = now; }
    },
    async abort(scope) { m.delete(scope); },
    size: () => m.size,
  };
}
