    if (b.state === "mismatch") return fail(ctx, 422, "idempotency_mismatch", "this Idempotency-Key was used for a different request");
    if (b.state === "in_flight") return fail(ctx, 409, "idempotency_in_flight", "the first request with this Idempotency-Key is still running; retry shortly", undefined, { "retry-after": "2" });
