      if (scope) await writes.idempotency.abort(scope);
      return fail(ctx, 403, "not_allowed", "this account cannot use Cyrus yet");
    }
    const out = await RUN[op]({ ...a, body });
    if (scope) { if (out.status < 500) await writes.idempotency.finish(scope, { status: out.status, body: out.body }, a.now().getTime()); else await writes.idempotency.abort(scope); }
    if (!isRead) await writes.audit({ subject: caller.subject!, client: caller.key.client, keyId: caller.key.id, op, target: out.target, status: out.status, requestId: ctx.requestId, replay: false }).catch(() => undefined);
