function withRequestId(body: unknown, ctx: Ctx): unknown {
  if (body && typeof body === "object" && "error" in body && (body as { error: unknown }).error && typeof (body as { error: unknown }).error === "object") {
    return { error: { ...((body as { error: Record<string, unknown> }).error), requestId: ctx.requestId } };
  }
  return body;
}

