const ID_RE = /^[A-Za-z0-9_-]{1,64}$/;

function parse<S extends z.ZodType>(schema: S, body: string): { ok: true; v: z.output<S> } | { ok: false; issues: ApiIssue[] } {
  let raw: unknown;
  try { raw = JSON.parse(body || "null"); } catch { return { ok: false, issues: [{ path: "", code: "bad_json", message: "send a JSON object" }] }; }
  const r = schema.safeParse(raw);
  if (r.success) return { ok: true, v: r.data };
  return { ok: false, issues: r.error.issues.slice(0, 20).map((i) => ({ path: i.path.join("."), code: i.code, message: i.message })) };
}

