    const r = await writes.installStatus(caller.subject!, id);
    return r.ok ? { status: 200, body: r.value, target: id } : err(r, id);
  },
  async putConfigValues({ params, caller, writes, body, getProject }) {
    const id = params.projectId ?? "";
    const proj = PROJECT_RE.test(id) ? await getProject(id) : null;
    // not the subject's (or no build yet) looks exactly like unknown
    if (!proj || proj.userId !== caller.subject || !proj.rootBuildId) return err({ status: 404, code: "not_found", message: "not found" });
    const p = parse(ConfigValuesZ, body);
    if (!p.ok) return bad(p.issues);
    if (p.v.action === "save" && !p.v.expectedHeadId) return bad([{ path: "expectedHeadId", code: "required", message: "save needs the head revision you last saw" }]);
    if (Object.keys(p.v.values).length > 400) return bad([{ path: "values", code: "too_big", message: "too many settings in one request" }]);
    const r = await writes.configValues(caller.subject!, { rootBuildId: proj.rootBuildId, action: p.v.action, values: p.v.values, expectedHeadId: p.v.expectedHeadId, message: p.v.message });
