  },
  async contributeLibraryAsset({ caller, writes, body }) {
    const p = parse(ContributeAssetZ, body);
    if (!p.ok) return bad(p.issues);
    const r = await writes.contribute(caller.subject!, p.v);
    return r.ok ? { status: 200, body: r.value, target: r.value.ref } : err(r);
  },
};

