// Real wiring of the Cyrus API v1 WRITE operations (./writes.ts). SERVER ONLY. Each one calls the product's own code
// with the API subject as the user, so every existing gate applies unchanged:
//   createProject   engine-core createProject (namespace reservation)
//   createBuild     host.builds.create = the build route's createModBuild (plan, tokens, suspension, rate limits)
//   createInstall   the delivery handler (lib/cyrus/delivery/api.ts) with the subject as the caller: CYRUS_DELIVERY,
//                   ownership, compatibility, consent, acknowledgements, Test Flight block, one job per server
//   putConfigValues the Config Studio service (CYRUS_CONFIG_STUDIO): ownership, optimistic head check, revisions
//   contribute      the library contribution pipeline (CYRUS_LIBRARY_BACKEND + CYRUS_LIBRARY_CONTRIBUTE)
// The delivery deps come from the route (they live with the platform's install code). HOST SEAM: no Nxeon imports.
import { createHash } from "node:crypto";
import { getHost } from "../../host";
import { createProject, EngineStoreError } from "../../engine-core/store";
import { handleDeliveryStatus, handleRequestDelivery, type DeliveryApiDeps } from "../../delivery/api";
import type { DeliveryStatus } from "../../delivery/request";
import { configServiceDeps } from "../../config/deps";
import { configStudioOn } from "../../config/route";
import { ConfigError, previewConfig, saveConfigValues } from "../../config/service";
import { libraryFlags } from "../../library/backend/flags";
import { libraryHttpDeps, libraryObjectStore } from "../../library/backend/runtime";
import { contributeAsset } from "../../library/backend/contribute";
import { contributorIdOf } from "../../library/backend/studio-hook";
import { catalogRef } from "../../library/v2/entry";
import { minecraftAssetProfile } from "../../adapters/minecraft";
import { createMemoryIdempotencyStore } from "./idempotency";
import type { InstallView, Outcome, V1WriteDeps } from "./writes";
import type { V1Deps } from "./http";

const idempotency = createMemoryIdempotencyStore();
const CONTRIBUTE_MAX_BYTES = 6 * 1024 * 1024;

const no = (status: number, code: string, message: string, detail?: Record<string, unknown>): Outcome<never> => ({ ok: false, status, code, message, ...(detail ? { detail } : {}) });

/** A delivery status as the v1 Install resource (the full status rides along as `delivery`). */
export function installViewOf(st: DeliveryStatus, now: Date): InstallView {
  const status: InstallView["status"] = st.pending ? (st.state === "running" ? "running" : "queued")
    : st.ok ? "succeeded" : st.state === "rolled_back" || st.state === "rollback_incomplete" ? "rolledback" : "failed";
  const extra = st as unknown as { createdAt?: string | Date; finishedAt?: string | Date | null };
  const isoOf = (v: string | Date | null | undefined) => (v ? new Date(v).toISOString() : null);
  return {
    id: st.jobId, buildId: st.subject?.buildId ?? null, serverId: st.serverId, status,
    error: st.ok === false ? st.headline : null,
    createdAt: isoOf(extra.createdAt) ?? now.toISOString(), finishedAt: st.pending ? null : isoOf(extra.finishedAt), delivery: st,
  };
}

/** Internal JSON error ({ error, code, ...facts }) -> Outcome. */
async function fromResponse(res: Response): Promise<{ status: number; json: Record<string, unknown> }> {
  const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
  return { status: res.status, json };
}
const refusal = (status: number, json: Record<string, unknown>) => {
  const { error, code, ...rest } = json;
  return no(status, typeof code === "string" ? code : status === 404 ? "not_found" : "refused", typeof error === "string" ? error : "refused", Object.keys(rest).length ? rest : undefined);
};

export function v1WriteDeps(o: { env: Record<string, string | undefined>; store: V1Deps["store"]; delivery?: DeliveryApiDeps; now?: () => Date }): V1WriteDeps {
  const now = o.now ?? (() => new Date());
  const asCaller = (subject: string): DeliveryApiDeps | null => (o.delivery ? { ...o.delivery, currentUser: async () => ({ id: subject }) } : null);
  return {
    idempotency,
    async audit(e) {
      await getHost().audit.append({
        userId: e.subject, action: `cyrus.api.${e.op}`, category: "cyrus", target: e.target ?? undefined,
        detail: JSON.stringify({ client: e.client, keyId: e.keyId, status: e.status, requestId: e.requestId, replay: e.replay }),
      });
    },
    mayUseCyrus: async (subject) => !!(await getHost().builds.accountFor(subject)),

    async createProject(subject, input) {
      try {
        const p = await createProject({ userId: subject, game: input.game, title: input.title });
        const row = await o.store.getProject(p.id);
        return row ? { ok: true, value: row } : no(500, "internal", "the project was created but cannot be read back");
      } catch (e) {
        if (e instanceof EngineStoreError) return no(400, e.code, e.message);
        throw e;
      }
    },

    async createBuild(subject, input) {
      const user = await getHost().builds.accountFor(subject);
      if (!user) return no(403, "not_allowed", "this account cannot use Cyrus yet");
      const r = await getHost().builds.create(user, { ...input });
      if (!r.ok) return refusal(r.status, r.json);
      const row = await o.store.getBuild(r.build.id);
      return row ? { ok: true, value: row } : no(500, "internal", "the build was queued but cannot be read back");
    },

    async requestInstall(subject, input, idemKey) {
      const d = asCaller(subject);
      if (!d) return no(503, "installs_unavailable", "installs are not wired on this deployment");
      // the delivery layer has its own idempotency (same key -> same job); derive a key it accepts from ours
      const key = `api.${createHash("sha256").update(`${subject}:${idemKey}`).digest("hex").slice(0, 40)}`;
      const req = new Request("http://cyrus.internal/api/cyrus/delivery/v1", {
        method: "POST", headers: { "content-type": "application/json", "idempotency-key": key },
        body: JSON.stringify({ op: "deliver", buildId: input.buildId, serverId: input.serverId, restartPolicy: input.restartPolicy, acked: input.acked, acceptCapabilities: input.acceptCapabilities ?? null, preview: input.preview }),
      });
      const { status, json } = await fromResponse(await handleRequestDelivery(req, d));
      if (status >= 400) return refusal(status, json);
      if (json.preview) return { ok: true, status: 200, value: json };
      const st = json.status as DeliveryStatus | null;
      if (!st) return { ok: true, status: 202, value: { id: String(json.jobId), buildId: input.buildId, serverId: input.serverId, status: "queued", error: null, createdAt: now().toISOString(), finishedAt: null } };
      return { ok: true, status: json.reused ? 200 : 202, value: installViewOf(st, now()) };
    },

    async installStatus(subject, installId) {
      const d = asCaller(subject);
      if (!d) return no(503, "installs_unavailable", "installs are not wired on this deployment");
      const { status, json } = await fromResponse(await handleDeliveryStatus(installId, d));
      if (status >= 400) return refusal(status, json);
      return { ok: true, value: installViewOf(json.status as DeliveryStatus, now()) };
    },

    async configValues(subject, input) {
      if (!configStudioOn(o.env)) return no(404, "not_found", "not found");
      try {
        const svc = configServiceDeps();
        if (input.action === "preview") return { ok: true, status: 200, value: await previewConfig(svc, subject, input.rootBuildId, input.values) };
        return { ok: true, status: 201, value: await saveConfigValues(svc, { userId: subject, rootBuildId: input.rootBuildId, values: input.values, expectedHeadId: input.expectedHeadId!, message: input.message }) };
      } catch (e) {
        if (e instanceof ConfigError) return no(e.status, e.code, e.message, Object.keys(e.extra).length ? e.extra : undefined);
        throw e;
      }
    },

    async contribute(subject, input) {
      const flags = libraryFlags(o.env);
      if (!flags.contribute || !flags.urlSecret) return no(503, "contributions_off", "library contributions are not enabled on this deployment");
      const b = libraryHttpDeps(o.env).backend();
      const objects = libraryObjectStore(o.env);
      if (!b || !objects) return no(503, "contributions_off", "the library backend is not available");
      const bytes = Buffer.from(input.bytesBase64, "base64");
      if (!bytes.length || bytes.length > CONTRIBUTE_MAX_BYTES) return no(413, "too_large", `the file must be 1 byte to ${CONTRIBUTE_MAX_BYTES} bytes`);
      const r = await contributeAsset({
        studio: input.studio, kind: input.kind, format: input.format, bytes, name: input.name, tags: input.tags,
        manifest: { legalClass: input.legalClass, provenance: { source: input.source, derivedFrom: [] } },
        contributorId: contributorIdOf(flags.urlSecret, subject),
      }, { enabled: true, catalog: b.catalog, index: b.index, objects, records: b.records, profiles: [minecraftAssetProfile], now });
      const id = "entry" in r ? r.entry.id : "entryId" in r ? r.entryId : null;
      return { ok: true, value: { outcome: r.outcome, ref: id ? catalogRef(id) : null, reason: r.reason ?? null } };
    },
  };
}

