export function v1Deps(env: Record<string, string | undefined> = process.env, extra: { delivery?: DeliveryApiDeps } = {}): V1Deps {
  const store: V1Deps["store"] = {
      listProjects: (userId, limit, after) => cyrusDb.cyrusProject.findMany({
      where: { userId, ...(after ? { OR: [{ createdAt: { lt: after.createdAt } }, { createdAt: after.createdAt, id: { lt: after.id } }] } : {}) },
      orderBy: [{ createdAt: "desc" }, { id: "desc" }], take: limit, select: PROJECT_SELECT,
    }),
    getProject: (id) => cyrusDb.cyrusProject.findUnique({ where: { id }, select: PROJECT_SELECT }),
    revisions: (ids) => cyrusDb.cyrusRevision.findMany({ where: { id: { in: ids } }, select: { id: true, projectId: true, seq: true, kind: true, status: true, message: true, modBuildId: true, manifest: true, spec: true, createdAt: true } }),
    getBuild: (id) => cyrusDb.modBuild.findUnique({
      where: { id },
      select: { id: true, userId: true, status: true, prompt: true, changeRequest: true, baseBuildId: true, rootBuildId: true, mcVersion: true, pluginName: true, version: true, result: true, error: true, errorCode: true, attempts: true, durationMs: true, jarName: true, jarSize: true, jarSha256: true, cyrus: true, createdAt: true, updatedAt: true, finishedAt: true },
    }),

  };
  return {
    config: () => apiV1Config(env),
    now: () => new Date(),
    replay,
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(key, { max, windowMs }),
    store,
    writes: v1WriteDeps({ env, store, delivery: extra.delivery }),
    catalog: () => fileCatalog(apiV1Config(env).catalogFile),
    planOf: (userId) => tierOf(userId),
    // same fail-closed licence rule as the sound library (lib/cyrus/sound/host.ts soundLibraryCleared)
    proprietaryCleared: () => env.CYRUS_SOUND_LIBRARY_CLEARED === "1",
    log: (m) => console.error(m),
  };
}

