// Cyrus API v1 (external, token-authenticated; off unless CYRUS_API_V1). Logic: lib/cyrus/api/v1/http.ts. Contract: docs/api/cyrus-v1.openapi.yaml.
import { handleV1 } from "@/lib/cyrus/api/v1/http";
