// Cyrus -> caller (Nxeon) WEBHOOKS: event builders, a transactional-outbox interface, and the dispatcher that signs,
// sends and retries. Contract: the `webhooks` section of docs/api/cyrus-v1.openapi.yaml (schemas in ./schemas.ts).
//   headers  Cyrus-Webhook-Id, Cyrus-Webhook-Timestamp (unix s), Cyrus-Signature: v1=<hex HMAC-SHA256(secret, id.ts.body)>
//            (./signing.ts signWebhook; the receiver drops anything older than 300 s and any id it has seen in 24 h)
//   delivery at-least-once; 2xx = done; anything else (or no answer in 10 s) is retried after 1 m, 5 m, 30 m, 2 h, 12 h,
//            then the event is DEAD (kept for an admin to replay). Each event carries current state, never a delta, so
//            order between events does not matter.
// OFF unless CYRUS_API_V1_WEBHOOKS=1 with a URL and a dedicated secret (>= 32 chars, never AUTH_SECRET). No product code
// emits events yet (emission points are listed in docs/CYRUS-MOVE-RUNBOOK.md); the Postgres outbox table is proposed in
// prisma/manual-migration-cyrus-api-v1.sql (NOT run). Pure apart from fetch. HOST SEAM: no Nxeon imports.
import { randomBytes } from "node:crypto";
import { signWebhook } from "./signing";
import type { WebhookEvent } from "./schemas";

export const WEBHOOK_RETRY_DELAYS_MS = [60_000, 5 * 60_000, 30 * 60_000, 2 * 3600_000, 12 * 3600_000] as const;
export const WEBHOOK_TIMEOUT_MS = 10_000;

export type WebhookEnvelope<D = Record<string, unknown>> = { id: string; type: WebhookEvent; createdAt: string; subject: string | null; data: D };
export type OutboxRow = { id: string; type: WebhookEvent; subject: string | null; body: string; attempts: number; nextAttemptAt: Date; status: "pending" | "sent" | "dead"; lastError: string | null; createdAt: Date };

export interface WebhookOutbox {
  /** Record the event (in the same transaction as the change it describes, for the Postgres outbox). Idempotent by id. */
  add(e: WebhookEnvelope): Promise<void>;
  /** Pending events whose time has come, oldest first. A multi-worker store claims them (FOR UPDATE SKIP LOCKED). */
  due(now: Date, limit: number): Promise<OutboxRow[]>;
  markSent(id: string, now: Date): Promise<void>;
  markFailed(id: string, a: { attempts: number; nextAttemptAt: Date | null; error: string }): Promise<void>;
}

export type WebhookTarget = { url: string; secret: string };
export function webhookTarget(env: Record<string, string | undefined> = process.env): WebhookTarget | null {
  if (env.CYRUS_API_V1_WEBHOOKS !== "1") return null;
  const url = env.CYRUS_API_V1_WEBHOOK_URL?.trim() ?? "", secret = env.CYRUS_API_V1_WEBHOOK_SECRET ?? "";
  if (!/^https?:\/\/[^\s]+$/.test(url) || secret.length < 32 || secret === env.AUTH_SECRET) return null; // fail closed
  return { url, secret };
}

// ------------------------------------------------------------------------------------------------ events
const newId = () => `evt_${randomBytes(12).toString("hex")}`;
function envelope<D extends Record<string, unknown>>(type: WebhookEvent, subject: string | null, data: D, now: Date, id = newId()): WebhookEnvelope<D> {
  return { id, type, createdAt: now.toISOString(), subject, data };
}
/** A build reached succeeded/failed. Deterministic id per build + status, so a double emit is one event. */
export const buildFinished = (b: { id: string; userId: string; status: string; jarSha256: string | null; errorCode: string | null; projectId?: string | null }, now = new Date()) =>
  envelope("build.finished", b.userId, { buildId: b.id, projectId: b.projectId ?? null, status: b.status === "succeeded" ? "succeeded" : "failed", jarSha256: b.jarSha256, errorCode: b.errorCode }, now, `evt_build_${b.id}_${b.status}`);
export const modPublished = (m: { userId: string; slug: string; buildId: string; version: string | null }, now = new Date()) =>
  envelope("mod.published", m.userId, { slug: m.slug, buildId: m.buildId, version: m.version }, now, `evt_mod_${m.slug}_${m.buildId}`);
export const installResult = (i: { userId: string; installId: string; serverId: string; ok: boolean; restartRequired: boolean; error: string | null }, now = new Date()) =>
  envelope("install.result", i.userId, { installId: i.installId, serverId: i.serverId, ok: i.ok, restartRequired: i.restartRequired, error: i.error }, now, `evt_install_${i.installId}`);
export const deliveryRolledBack = (d: { userId: string; deliveryId: string; serverId: string; failedStep: string; reason: string }, now = new Date()) =>
  envelope("delivery.rolledback", d.userId, { deliveryId: d.deliveryId, serverId: d.serverId, failedStep: d.failedStep, reason: d.reason }, now, `evt_rollback_${d.deliveryId}`);
export const libraryContributed = (l: { userId: string | null; ref: string; kind: string; status: "pending-checks" | "published" | "held" }, now = new Date()) =>
  envelope("library.contributed", l.userId, { ref: l.ref, kind: l.kind, status: l.status }, now, `evt_lib_${l.ref.replace(/[^A-Za-z0-9]/g, "")}_${l.status}`);

/** Emit = add to the outbox, only when webhooks are configured. Never throws into the caller's flow. */
export async function emitWebhook(outbox: WebhookOutbox | null, e: WebhookEnvelope, env: Record<string, string | undefined> = process.env): Promise<boolean> {
  if (!outbox || !webhookTarget(env)) return false;
  try { await outbox.add(e); return true; } catch (err) { console.error("[cyrus-webhooks] outbox add failed", e.type, (err as Error).message); return false; }
}

// ------------------------------------------------------------------------------------------------ dispatch
export type DispatchResult = { sent: number; retried: number; dead: number };
/** One pass (the worker calls it every minute or so): send what is due, schedule retries, bury what ran out of tries. */
export async function dispatchWebhooks(a: { outbox: WebhookOutbox; target: WebhookTarget; now?: () => Date; fetch?: typeof fetch; limit?: number }): Promise<DispatchResult> {
  const now = a.now ?? (() => new Date());
  const doFetch = a.fetch ?? fetch;
  const out: DispatchResult = { sent: 0, retried: 0, dead: 0 };
  for (const row of await a.outbox.due(now(), a.limit ?? 50)) {
    const ts = String(Math.floor(now().getTime() / 1000));
    let error: string | null = null;
    const ac = new AbortController();
    const timer = setTimeout(() => ac.abort(), WEBHOOK_TIMEOUT_MS);
    try {
      const res = await doFetch(a.target.url, {
        method: "POST", signal: ac.signal, redirect: "manual",
        headers: { "content-type": "application/json", "cyrus-webhook-id": row.id, "cyrus-webhook-timestamp": ts, "cyrus-signature": signWebhook(a.target.secret, row.id, ts, row.body), "user-agent": "cyrus-webhooks/1" },
        body: row.body,
      });
      if (res.status < 200 || res.status >= 300) error = `HTTP ${res.status}`;
    } catch (e) {
      error = ac.signal.aborted ? `no answer within ${WEBHOOK_TIMEOUT_MS} ms` : (e as Error).message || "network";
    } finally { clearTimeout(timer); }
    if (!error) { await a.outbox.markSent(row.id, now()); out.sent++; continue; }
    const attempts = row.attempts + 1;
    const delay = WEBHOOK_RETRY_DELAYS_MS[attempts - 1];
    await a.outbox.markFailed(row.id, { attempts, nextAttemptAt: delay === undefined ? null : new Date(now().getTime() + delay), error: error.slice(0, 300) });
    if (delay === undefined) out.dead++; else out.retried++;
  }
  return out;
}

/** In-process outbox (tests, a single dev instance). */
export function createMemoryOutbox(): WebhookOutbox & { rows: Map<string, OutboxRow> } {
  const rows = new Map<string, OutboxRow>();
  return {
    rows,
    async add(e) {
      if (rows.has(e.id)) return;
      rows.set(e.id, { id: e.id, type: e.type, subject: e.subject, body: JSON.stringify(e), attempts: 0, nextAttemptAt: new Date(e.createdAt), status: "pending", lastError: null, createdAt: new Date(e.createdAt) });
    },
    async due(now, limit) {
      return [...rows.values()].filter((r) => r.status === "pending" && r.nextAttemptAt <= now).sort((x, y) => +x.createdAt - +y.createdAt).slice(0, limit);
    },
    async markSent(id) { const r = rows.get(id); if (r) { r.status = "sent"; r.lastError = null; } },
    async markFailed(id, f) {
      const r = rows.get(id);
      if (!r) return;
      r.attempts = f.attempts; r.lastError = f.error;
      if (f.nextAttemptAt) r.nextAttemptAt = f.nextAttemptAt; else r.status = "dead";
    },
  };
}

