// NXEON SIDE: the receiver for Cyrus webhooks (Cyrus -> Nxeon). Framework-free (Request -> Response); a later Nxeon
// route (e.g. app/api/webhooks/cyrus/route.ts) wraps it. NOTHING mounts it today. Imports nothing from lib/cyrus.
// Checks, in order: body size -> headers present -> timestamp within 300 s -> HMAC-SHA256 signature (several "v1=" values
// allowed during a secret rotation, constant-time) -> exactly-once by event id (24 h) -> JSON envelope -> the handler.
// 2xx tells Cyrus "done"; a handler throw answers 500 so Cyrus retries (the id is released so the retry is processed).
import { createHmac, timingSafeEqual } from "node:crypto";

export const CYRUS_WEBHOOK_EVENTS = ["build.finished", "mod.published", "install.result", "delivery.rolledback", "library.contributed"] as const;
export type CyrusWebhookType = (typeof CYRUS_WEBHOOK_EVENTS)[number];
export type CyrusWebhook = { id: string; type: CyrusWebhookType; createdAt: string; subject: string | null; data: Record<string, unknown> };

export const RECEIVER_TOLERANCE_S = 300;
export const RECEIVER_MAX_BODY = 256 * 1024;

/** Remembers processed ids (memory here; the CyrusWebhookReceipt table for several instances). */
export interface ReceiptStore {
  /** true when newly recorded; false when already seen */
  claim(id: string, type: string, nowMs: number): Promise<boolean>;
  release(id: string): Promise<void>;
}
export function createMemoryReceipts(ttlMs = 24 * 3600_000): ReceiptStore {
  const m = new Map<string, number>();
  return {
    async claim(id, _type, now) {
      for (const [k, t] of m) { if (t + ttlMs < now) m.delete(k); else break; }
      if (m.has(id)) return false;
      m.set(id, now);
      return true;
    },
    async release(id) { m.delete(id); },
  };
}

export const expectedSignature = (secret: string, id: string, ts: string, body: string) => `v1=${createHmac("sha256", secret).update(`${id}.${ts}.${body}`).digest("hex")}`;
function same(a: string, b: string): boolean {
  const x = Buffer.from(a), y = Buffer.from(b);
  return x.length === y.length && timingSafeEqual(x, y);
}

export type ReceiverOptions = {
  /** current secret, plus the previous one during a rotation */
  secrets: string[];
  receipts: ReceiptStore;
  handle: (e: CyrusWebhook) => Promise<void>;
  now?: () => number;
  log?: (m: string) => void;
};

const reply = (status: number, body: Record<string, unknown>) => Response.json(body, { status, headers: { "cache-control": "no-store" } });

export async function receiveCyrusWebhook(req: Request, o: ReceiverOptions): Promise<Response> {
  const now = (o.now ?? Date.now)();
  if (req.method !== "POST") return reply(405, { error: "method" });
  if (!o.secrets.some((s) => s.length >= 32)) return reply(503, { error: "receiver not configured" });
  const body = await req.text();
  if (body.length > RECEIVER_MAX_BODY) return reply(413, { error: "too large" });
  const id = req.headers.get("cyrus-webhook-id"), ts = req.headers.get("cyrus-webhook-timestamp"), sig = req.headers.get("cyrus-signature");
  if (!id || !/^[A-Za-z0-9_.:-]{4,128}$/.test(id) || !ts || !/^\d{9,11}$/.test(ts) || !sig) return reply(400, { error: "unsigned" });
  if (Math.abs(Math.floor(now / 1000) - Number(ts)) > RECEIVER_TOLERANCE_S) return reply(400, { error: "stale" });
  const sent = sig.split(/[ ,]+/).filter(Boolean);
  if (!o.secrets.filter((s) => s.length >= 32).some((s) => sent.some((v) => same(v, expectedSignature(s, id, ts, body))))) return reply(401, { error: "bad signature" });
  let e: CyrusWebhook;
  try {
    e = JSON.parse(body) as CyrusWebhook;
    if (!e || e.id !== id || !(CYRUS_WEBHOOK_EVENTS as readonly string[]).includes(e.type) || typeof e.data !== "object" || e.data === null) throw new Error("shape");
  } catch { return reply(400, { error: "bad envelope" }); }
  if (!(await o.receipts.claim(id, e.type, now))) return reply(200, { ok: true, duplicate: true });
  try {
    await o.handle(e);
    return reply(200, { ok: true });
  } catch (err) {
    await o.receipts.release(id);
    o.log?.(`[cyrus-webhook] ${e.type} ${id} failed: ${(err as Error).message}`);
    return reply(500, { error: "handler failed" });
  }
}

