// Cyrus API v1 phase 2 writes (lib/cyrus/api/v1/writes.ts) through handleV1 with fake deps: flag/scope/idempotency
// gates, replay + mismatch + in-flight, the access rule, every operation's happy path validated against the Zod
// schemas the OpenAPI file is generated from, refusals passed through, audit rows, and the install status mapping.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { generateKeyPairSync, randomBytes, type KeyObject } from "node:crypto";
import { handleV1, type BuildRow, type ProjectRow, type V1Deps } from "../lib/cyrus/api/v1/http";
import { mintServiceToken, mintSubjectAssertion, ReplayCache } from "../lib/cyrus/api/v1/signing";
import { BuildZ, ContributionZ, ErrorZ, InstallZ, ProjectZ } from "../lib/cyrus/api/v1/schemas";
import { createMemoryIdempotencyStore } from "../lib/cyrus/api/v1/idempotency";
import { installViewOf, type ApiAuditEvent, type V1WriteDeps, type WriteOperationId } from "../lib/cyrus/api/v1/writes";

const NOW = new Date("2026-10-11T12:00:00Z");
const kp = generateKeyPairSync("ed25519");
const spki = (k: KeyObject) => k.export({ format: "der", type: "spki" }).toString("base64");
const writer = mintServiceToken("nxeon02");
const reader = mintServiceToken("nxeon03");
const ENV = {
  CYRUS_API_V1: "1",
  CYRUS_API_V1_KEYS: JSON.stringify([
    { id: "nxeon02", client: "nxeon", sha256: writer.sha256, scopes: ["projects:write", "builds:write", "installs:write", "installs:read", "config:write", "library:write"] },
    { id: "nxeon03", client: "nxeon", sha256: reader.sha256, scopes: ["projects:read"] },
  ]),
  CYRUS_API_V1_SUBJECT_KEYS: JSON.stringify([{ client: "nxeon", kid: "s1", publicKey: spki(kp.publicKey) }]),
};
const assertion = (sub: string) => mintSubjectAssertion({ v: 1, iss: "nxeon", sub, aud: "cyrus-api-v1", iat: Math.floor(NOW.getTime() / 1000), exp: Math.floor(NOW.getTime() / 1000) + 60, jti: randomBytes(9).toString("base64url"), kid: "s1" }, kp.privateKey);
const PID = "cp" + "1".padStart(20, "0");
const project = (userId: string, over: Partial<ProjectRow> = {}): ProjectRow => ({ id: PID, userId, game: "minecraft", namespace: "nx_abcd1234", title: "Shop", rootBuildId: "b1", headRevisionId: null, lastPassingRevisionId: null, revisionCount: 0, createdAt: NOW, updatedAt: NOW, ...over });
const build = (over: Partial<BuildRow> = {}): BuildRow => ({ id: "b9", userId: "user_a", status: "queued", prompt: "a coin shop", changeRequest: null, baseBuildId: null, rootBuildId: "b9", mcVersion: "1.21.11", pluginName: null, version: null, result: null, error: null, errorCode: null, attempts: 0, durationMs: null, jarName: null, jarSize: null, jarSha256: null, cyrus: null, createdAt: NOW, updatedAt: NOW, finishedAt: null, ...over });

function setup(over: Partial<V1WriteDeps> = {}, deps: Partial<V1Deps> = {}) {
  const calls: Record<string, unknown[]> = {};
  const audit: ApiAuditEvent[] = [];
  const rec = (k: string, v: unknown) => { (calls[k] ??= []).push(v); };
  const projects = new Map<string, ProjectRow>([[PID, project("user_a")]]);
  const writes: V1WriteDeps = {
    idempotency: createMemoryIdempotencyStore(),
    audit: async (e) => { audit.push(e); },
    mayUseCyrus: async (s) => s !== "user_blocked",
    createProject: async (s, i) => { rec("createProject", [s, i]); return { ok: true, value: project(s, { id: "cp" + "2".padStart(20, "0"), title: i.title }) }; },
    createBuild: async (s, i) => { rec("createBuild", [s, i]); return i.prompt.includes("broke") ? { ok: false, status: 402, code: "tokens", message: "Not enough Cyrus tokens.", detail: { needed: 40 } } : { ok: true, value: build({ userId: s, prompt: i.prompt }) }; },
    requestInstall: async (s, i, k) => { rec("requestInstall", [s, i, k]); return i.acked.length ? { ok: true, status: 202, value: { id: "job1", buildId: i.buildId, serverId: i.serverId, status: "queued", error: null, createdAt: NOW.toISOString(), finishedAt: null } } : { ok: false, status: 409, code: "needs_ack", message: "Confirm the steps below first.", detail: { acks: [{ id: "restart" }] } }; },
    installStatus: async (s, id) => (id === "job1" ? { ok: true, value: { id, buildId: "b1", serverId: "s1", status: "succeeded", error: null, createdAt: NOW.toISOString(), finishedAt: NOW.toISOString() } } : { ok: false, status: 404, code: "not_found", message: "Not found" }),
    configValues: async (s, i) => { rec("configValues", [s, i]); return { ok: true, status: i.action === "save" ? 201 : 200, value: { files: [], diff: [] } }; },
    contribute: async (s, i) => { rec("contribute", [s, i.name]); return { ok: true, value: { outcome: "held", ref: "cat:abcdef123456", reason: "new contributor" } }; },
    ...over,
  };
  const d: V1Deps = {
    config: () => JSON.parse("null") ?? (undefined as never), now: () => NOW, replay: new ReplayCache(),
    rateLimit: () => ({ ok: true, retryAfterSec: 0, remaining: 99 }),
    store: { listProjects: async () => [], getProject: async (id) => projects.get(id) ?? null, revisions: async () => [], getBuild: async () => null },
    catalog: async () => null, planOf: async () => "katara", proprietaryCleared: () => false, requestId: () => "req_test", writes, ...deps,
  };
  return { d, calls, audit, projects };
}
// config from ENV through the real parser
import { apiV1Config } from "../lib/cyrus/api/v1/config";
const cfg = (env: Record<string, string | undefined> = ENV) => () => apiV1Config(env);

type Req = { method?: string; path: string; sub?: string | null; token?: string; key?: string | null; body?: unknown };
function req(r: Req): Request {
  const h: Record<string, string> = { authorization: `Bearer ${r.token ?? writer.token}`, "content-type": "application/json" };
  if (r.sub !== null) h["cyrus-subject"] = assertion(r.sub ?? "user_a");
  if (r.key !== null) h["idempotency-key"] = r.key ?? `k_${randomBytes(6).toString("hex")}`;
  const method = r.method ?? "POST";
  return new Request(`http://x/api/cyrus/v1${r.path}`, { method, headers: h, body: method === "GET" ? undefined : JSON.stringify(r.body ?? {}) });
}
const run = (s: ReturnType<typeof setup>, op: WriteOperationId, r: Req, params: Record<string, string> = {}) => handleV1(op, req(r), params, { ...s.d, config: cfg() });
const j = async (res: Response) => res.json() as Promise<Record<string, unknown>>;

describe("Cyrus API v1 writes: gates", () => {
  it("is invisible while CYRUS_API_V1 is off", async () => {
    const s = setup();
    const res = await handleV1("createProject", req({ path: "/projects", body: { game: "minecraft" } }), {}, { ...s.d, config: cfg({ ...ENV, CYRUS_API_V1: "0" }) });
    assert.equal(res.status, 404);
  });
  it("503 when the deployment has no write deps", async () => {
    const s = setup({}, { writes: undefined });
    assert.equal((await run(s, "createProject", { path: "/projects", body: { game: "minecraft" } })).status, 503);
  });
  it("403 without the write scope, 400 without a subject or an Idempotency-Key", async () => {
    const s = setup();
    assert.equal((await run(s, "createProject", { path: "/projects", token: reader.token, body: { game: "minecraft" } })).status, 403);
    assert.equal((await run(s, "createProject", { path: "/projects", sub: null, body: { game: "minecraft" } })).status, 400);
    const r = await run(s, "createProject", { path: "/projects", key: null, body: { game: "minecraft" } });
    assert.equal(r.status, 400);
    assert.equal(((await j(r)).error as { code: string }).code, "idempotency_key_required");
    assert.equal(s.calls.createProject, undefined);
  });
  it("403 not_allowed when the account may not use Cyrus, and the key is free again", async () => {
    const s = setup();
    const r = await run(s, "createProject", { path: "/projects", sub: "user_blocked", key: "same-key-1", body: { game: "minecraft" } });
    assert.equal(r.status, 403);
    assert.equal(((await j(r)).error as { code: string }).code, "not_allowed");
    assert.equal(s.calls.createProject, undefined);
  });
  it("bad bodies are 400 with issues and never reach the product", async () => {
    const s = setup();
    const r = await run(s, "createBuild", { path: "/builds", body: { prompt: "x" } });
    assert.equal(r.status, 400);
    const b = await j(r);
    ErrorZ.parse(b);
    assert.ok(((b.error as { issues: unknown[] }).issues).length > 0);
    assert.equal(s.calls.createBuild, undefined);
  });
});

describe("Cyrus API v1 writes: idempotency", () => {
  it("replays the first answer for the same key + request, once", async () => {
    const s = setup();
    const a = await run(s, "createProject", { path: "/projects", key: "idem-0001", body: { game: "minecraft", title: "Shop" } });
    const b = await run(s, "createProject", { path: "/projects", key: "idem-0001", body: { game: "minecraft", title: "Shop" } });
    assert.equal(a.status, 201); assert.equal(b.status, 201);
    assert.equal(b.headers.get("idempotent-replay"), "true");
    assert.deepEqual(await j(a), await j(b));
    assert.equal(s.calls.createProject.length, 1);
    assert.deepEqual(s.audit.map((x) => x.replay), [false, true]);
  });
  it("refuses the same key for a different request (422)", async () => {
    const s = setup();
    await run(s, "createProject", { path: "/projects", key: "idem-0002", body: { game: "minecraft" } });
    const r = await run(s, "createProject", { path: "/projects", key: "idem-0002", body: { game: "terraria" } });
    assert.equal(r.status, 422);
  });
  it("409 while the first request is still running; a crash frees the key", async () => {
    let release!: () => void;
    const gate = new Promise<void>((r) => { release = r; });
    let boom = true;
    const s = setup({ createProject: async (sub, i) => { await gate; if (boom) throw new Error("db down"); return { ok: true, value: project(sub, { title: i.title }) }; } });
    const first = run(s, "createProject", { path: "/projects", key: "idem-0003", body: { game: "minecraft" } });
    const second = await run(s, "createProject", { path: "/projects", key: "idem-0003", body: { game: "minecraft" } });
    assert.equal(second.status, 409);
    release();
    assert.equal((await first).status, 500);
    boom = false;
    assert.equal((await run(s, "createProject", { path: "/projects", key: "idem-0003", body: { game: "minecraft" } })).status, 201);
  });
  it("keys are scoped per subject", async () => {
    const s = setup();
    await run(s, "createProject", { path: "/projects", key: "idem-0004", body: { game: "minecraft" } });
    const r = await run(s, "createProject", { path: "/projects", sub: "user_b", key: "idem-0004", body: { game: "terraria" } });
    assert.equal(r.status, 201);
  });
});

describe("Cyrus API v1 writes: operations", () => {
  it("createProject -> 201 Project", async () => {
    const s = setup();
    const r = await run(s, "createProject", { path: "/projects", body: { game: "minecraft", title: "  Shop  " } });
    assert.equal(r.status, 201);
    ProjectZ.parse(await j(r));
    assert.deepEqual(s.calls.createProject[0], ["user_a", { game: "minecraft", title: "Shop" }]);
  });
  it("createBuild -> 202 Build; other games 400; refusals pass through with their facts", async () => {
    const s = setup();
    const ok = await run(s, "createBuild", { path: "/builds", body: { prompt: "a coin shop", target: { game: "minecraft", version: "1.21.11" } } });
    assert.equal(ok.status, 202);
    BuildZ.parse(await j(ok));
    assert.deepEqual(s.calls.createBuild[0], ["user_a", { prompt: "a coin shop", mcVersion: "1.21.11", baseBuildId: undefined, changeRequest: undefined, model: undefined }]);
    assert.equal((await run(s, "createBuild", { path: "/builds", body: { prompt: "a coin shop", target: { game: "rust", version: "1" } } })).status, 400);
    const broke = await run(s, "createBuild", { path: "/builds", body: { prompt: "broke shop", target: { game: "minecraft", version: "1.21.11" } } });
    assert.equal(broke.status, 402);
    const e = (await j(broke)).error as Record<string, unknown>;
    assert.equal(e.code, "tokens"); assert.equal(e.needed, 40); assert.equal(e.requestId, "req_test");
  });
  it("createInstall -> 202 Install; needs_ack 409 lists what to confirm; the Idempotency-Key reaches the delivery layer", async () => {
    const s = setup();
    const need = await run(s, "createInstall", { path: "/installs", body: { buildId: "b1", serverId: "s1" } });
    assert.equal(need.status, 409);
    assert.deepEqual(((await j(need)).error as { acks: unknown }).acks, [{ id: "restart" }]);
    const ok = await run(s, "createInstall", { path: "/installs", key: "inst-0001", body: { buildId: "b1", serverId: "s1", acked: ["restart"] } });
    assert.equal(ok.status, 202);
    InstallZ.parse(await j(ok));
    const [, input, key] = s.calls.requestInstall[1] as [string, Record<string, unknown>, string];
    assert.equal(key, "inst-0001"); assert.equal(input.restartPolicy, "now"); assert.equal(input.preview, false);
    assert.equal((await run(s, "createInstall", { path: "/installs", body: { buildId: "../x", serverId: "s1" } })).status, 400);
  });
  it("getInstall -> 200 Install; unknown 404", async () => {
    const s = setup();
    const r = await run(s, "getInstall", { method: "GET", path: "/installs/job1", key: null }, { installId: "job1" });
