    await dispatchWebhooks({ outbox: ob, target: webhookTarget(ENV)!, now: () => T0, fetch: w.f });
    const sent = w.sent[0];
    const body = await sent.clone().text();
    const headers = Object.fromEntries(sent.headers);
    const mk = (b: string, h: Record<string, string> = headers) => new Request("https://nxeon.test/x", { method: "POST", headers: h, body: b });
    const opts = (o: Partial<Parameters<typeof receiveCyrusWebhook>[1]> = {}) => ({ secrets: [SECRET], receipts: createMemoryReceipts(), now: () => T0.getTime(), handle: async () => {}, ...o });
