describe("Nxeon-side Cyrus client", () => {
  it("imports nothing from lib/cyrus (it stays with Nxeon when Cyrus moves)", () => {
    const dir = path.resolve(__dirname, "..", "lib", "cyrus-client");
    for (const f of readdirSync(dir)) {
      const src = readFileSync(path.join(dir, f), "utf8");
      for (const m of src.matchAll(/(?:from|import)\s*\(?\s*["']([^"']+)["']/g)) assert.ok(m[1].startsWith("node:") || m[1].startsWith("./"), `${f} imports ${m[1]}`);
    }
  });
  it("talks to the real handleV1: assertion verifies, writes carry one Idempotency-Key across retries", async () => {
    const kp = generateKeyPairSync("ed25519");
    const tok = mintServiceToken("nxeon09");
    const env = {
      CYRUS_API_V1: "1",
      CYRUS_API_V1_KEYS: JSON.stringify([{ id: "nxeon09", client: "nxeon", sha256: tok.sha256, scopes: ["projects:write", "projects:read"] }]),
      CYRUS_API_V1_SUBJECT_KEYS: JSON.stringify([{ client: "nxeon", kid: "s9", publicKey: kp.publicKey.export({ format: "der", type: "spki" }).toString("base64") }]),
    };
    const seenKeys: string[] = [];
    let created = 0;
    const deps: V1Deps = {
      config: () => apiV1Config(env), now: () => new Date(), replay: new ReplayCache(), rateLimit: () => ({ ok: true, retryAfterSec: 0, remaining: 1 }),
      store: { listProjects: async () => [], getProject: async () => null, revisions: async () => [], getBuild: async () => null },
      catalog: async () => null, planOf: async () => null, proprietaryCleared: () => false,
      writes: {
        idempotency: createMemoryIdempotencyStore(), audit: async () => {}, mayUseCyrus: async () => true,
        createProject: async (sub, i) => { created++; return { ok: true, value: { id: "cp" + "9".padStart(20, "0"), userId: sub, game: i.game, namespace: "nx_00000000", title: i.title, rootBuildId: null, headRevisionId: null, lastPassingRevisionId: null, revisionCount: 0, createdAt: new Date(), updatedAt: new Date() } }; },
        createBuild: async () => { throw new Error("unused"); }, requestInstall: async () => { throw new Error("unused"); }, installStatus: async () => { throw new Error("unused"); },
        configValues: async () => { throw new Error("unused"); }, contribute: async () => { throw new Error("unused"); },
      },
    };
    let flaky = 1;
    const f = (async (url: string | URL, init?: RequestInit) => {
      const r = new Request(url, init);
      if (r.method === "POST") seenKeys.push(r.headers.get("idempotency-key") ?? "");
      if (flaky-- > 0) return new Response("{}", { status: 503 });
      return handleV1(new URL(r.url).pathname.endsWith("/projects") && r.method === "POST" ? "createProject" : "getHealth", r, {}, deps);
    }) as typeof fetch;
    const c = createCyrusClient({ baseUrl: "https://cyrus.test/api/cyrus/v1", token: tok.token, issuer: "nxeon", subjectKey: { kid: "s9", privateKey: kp.privateKey }, fetch: f, sleep: async () => {} });
    const p = await c.createProject("user_a", { game: "minecraft", title: "Shop" });
    assert.equal(p.title, "Shop");
    assert.equal(created, 1);
    assert.equal(seenKeys.length, 2); assert.equal(seenKeys[0], seenKeys[1], "same key on the retry");
    await assert.rejects(c.createProject("someone@example.com", { game: "minecraft" }), /never an email/);
    const h = await c.health();
    assert.equal(h.client, "nxeon");
    const bad = createCyrusClient({ baseUrl: "https://cyrus.test/api/cyrus/v1", token: `cyk_nxeon09_${randomBytes(32).toString("base64url")}`, issuer: "nxeon", subjectKey: { kid: "s9", privateKey: kp.privateKey }, fetch: f, sleep: async () => {} });
    await assert.rejects(bad.health(), (e: unknown) => e instanceof CyrusApiError && e.status === 401 && e.code === "unauthorized");
  });
});

